query:
-- Récupérer les IDs des molécules et plantes pour créer des relations
-- D'abord, voir les molécules disponibles
SELECT id, name FROM molecules WHERE name LIKE '%linalol%' OR name LIKE '%Linalol%' OR name LIKE '%limonene%' OR name LIKE '%Limonene%' OR name LIKE '%myrcene%' OR name LIKE '%Myrcene%' LIMIT 20;

